css:
@page {
    size: 80mm auto;
    margin: 0;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body,
.print-format {
    font-size: 12px;
    line-height: 1.4;
    color: #1a1a1a;
    background: #fff;
    width: 72mm;
    margin: 0 auto;
    padding: 3mm;
}

.po-receipt {
    width: 100%;
    padding: 0;
}

.po-header {
    text-align: center;
    padding-bottom: 6px;
    border-bottom: 2px solid #000;
}

.store-logo {
    max-height: 48px;
    max-width: 48px;
    margin: 0 auto 4px;
    display: block;
    border-radius: 4px;
}

.store-name {
    font-size: 16px;
    font-weight: 900;
    letter-spacing: 1px;
    text-transform: uppercase;
    margin-bottom: 2px;
}

.store-detail {
    font-size: 9px;
    color: #444;
    line-height: 1.5;
}

.div-dashed {
    border: none;
    border-top: 1px dashed #999;
    margin: 5px 0;
}

.div-solid {
    border: none;
    border-top: 1px solid #000;
    margin: 5px 0;
}

.po-title {
    text-align: center;
    font-size: 14px;
    font-weight: 900;
    letter-spacing: 2px;
    text-transform: uppercase;
    padding: 4px 0;
}

.po-meta {
    font-size: 10px;
    padding: 3px 0;
}

.meta-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    padding: 1px 0;
}

.meta-label {
    color: #666;
    font-weight: 400;
}

.meta-value {
    font-weight: 600;
    text-align: right;
}

.items-header {
    display: flex;
    justify-content: space-between;
    font-size: 9px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    padding: 3px 0;
    border-bottom: 1px solid #000;
    color: #333;
}

.items-header .col-sno {
    width: 18px;
    text-align: center;
}

.items-header .col-item {
    flex: 1;
    padding-left: 4px;
}

.items-header .col-qty {
    width: 40px;
    text-align: right;
}

.item-row {
    display: flex;
    justify-content: space-between;
    padding: 2px 0;
    border-bottom: 1px dotted #ddd;
    font-size: 10px;
}

.item-row:last-child {
    border-bottom: none;
}

.item-row .col-sno {
    width: 18px;
    text-align: center;
    color: #999;
}

.item-row .col-item {
    flex: 1;
    padding-left: 4px;
    font-weight: 600;
    word-break: break-word;
}

.item-row .col-qty {
    width: 40px;
    text-align: right;
    font-weight: 700;
}

.total-section {
    padding: 4px 0;
}

.total-row {
    display: flex;
    justify-content: space-between;
    font-size: 11px;
    font-weight: 700;
    padding: 2px 0;
}

.po-footer {
    text-align: center;
    padding-top: 5px;
    border-top: 2px solid #000;
    font-size: 8px;
    color: #999;
}

@media print {
    body,
    .print-format {
        width: 72mm;
        margin: 0;
        padding: 2mm;
    }

    .page-break {
        display: none;
    }
}
